import { NextRequest, NextResponse } from 'next/server'
import { Types } from 'mongoose'
import { connectDB } from '@/lib/db'
import { Vendor } from '@/models/vendor'
import { VendorDeliveryRule } from '@/models/vendor-delivery-rule'
import CampusLocation from '@/models/campus-location'
export async function GET(_request: NextRequest, { params }: { params: Promise<{ id: string }> }) { const { id } = await params; if (!Types.ObjectId.isValid(id)) return NextResponse.json({ error: 'Invalid vendor.' }, { status: 400 }); await connectDB(); const vendor = await Vendor.findOne({ _id: id, active: true, pickupParentLocationId: { $ne: null } }).lean(); if (!vendor) return NextResponse.json({ error: 'Vendor unavailable.' }, { status: 404 }); const pickup = await CampusLocation.findOne({ _id: vendor.pickupParentLocationId, parentLocationId: null, active: true }).select('_id name').lean(); if (!pickup) return NextResponse.json({ error: 'Vendor pickup is unavailable.' }, { status: 409 }); const rules = await VendorDeliveryRule.find({ vendorId: vendor._id, enabled: true }).lean(); const parents = await CampusLocation.find({ _id: { $in: rules.map(r => r.dropoffParentLocationId) }, parentLocationId: null, active: true }).select('_id name deliveryPolicy').sort({ name: 1 }).lean(); const fees = new Map(rules.map(r => [String(r.dropoffParentLocationId), r.serviceFee])); return NextResponse.json({ vendor: { id: String(vendor._id), name: vendor.name, serviceType: vendor.serviceType }, pickup: { parentLocationId: String(pickup._id), name: pickup.name }, destinations: parents.map(parent => ({ parentLocationId: String(parent._id), name: parent.name, serviceFee: fees.get(String(parent._id)), requiresRoomNumber: parent.deliveryPolicy?.requiresRoomNumber === true })) }) }
